(12,1,'2026-03-26 16:29:31','2026-03-26 15:29:31','<!-- wp:site-logo {\"width\":150,\"shouldSyncIcon\":false,\"align\":\"center\"} /-->\n\n<!-- wp:paragraph {\"fontSize\":\"large\"} -->\n<p class=\"has-large-font-size\"><strong>Productos destacados</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:woocommerce/product-collection {\"queryId\":0,\"query\":{\"perPage\":3,\"pages\":1,\"offset\":0,\"postType\":\"product\",\"order\":\"asc\",\"orderBy\":\"title\",\"search\":\"\",\"exclude\":[],\"inherit\":false,\"taxQuery\":[],\"isProductCollectionBlock\":true,\"featured\":true,\"woocommerceOnSale\":false,\"woocommerceStockStatus\":[\"instock\",\"outofstock\",\"onbackorder\"],\"woocommerceAttributes\":[],\"woocommerceHandPickedProducts\":[],\"filterable\":false,\"relatedBy\":{\"categories\":true,\"tags\":true}},\"tagName\":\"div\",\"displayLayout\":{\"type\":\"flex\",\"columns\":3,\"shrinkColumns\":true},\"dimensions\":{\"widthType\":\"fill\"},\"collection\":\"woocommerce/product-collection/featured\",\"hideControls\":[\"inherit\",\"featured\",\"filterable\"],\"queryContextIncludes\":[\"collection\"],\"__privatePreviewState\":{\"isPreview\":false,\"previewMessage\":\"Los productos reales pueden diferir en función de la página en la que se estén viendo.\"}} -->\n<div class=\"wp-block-woocommerce-product-collection\"><!-- wp:woocommerce/product-template {\"fontSize\":\"small\"} -->\n<!-- wp:woocommerce/product-image {\"showSaleBadge\":false,\"imageSizing\":\"thumbnail\",\"isDescendentOfQueryLoop\":true} /-->\n\n<!-- wp:post-title {\"textAlign\":\"center\",\"isLink\":true,\"style\":{\"spacing\":{\"margin\":{\"bottom\":\"0.75rem\",\"top\":\"0\"}},\"typography\":{\"lineHeight\":\"1.4\"}},\"fontSize\":\"medium\",\"__woocommerceNamespace\":\"woocommerce/product-collection/product-title\"} /-->\n\n<!-- wp:woocommerce/product-price {\"isDescendentOfQueryLoop\":true,\"textAlign\":\"center\",\"fontSize\":\"small\"} /-->\n\n<!-- wp:woocommerce/product-button {\"textAlign\":\"center\",\"isDescendentOfQueryLoop\":true,\"fontSize\":\"small\"} /-->\n<!-- /wp:woocommerce/product-template --></div>\n<!-- /wp:woocommerce/product-collection -->\n\n<!-- wp:paragraph {\"fontSize\":\"large\"} -->\n<p class=\"has-large-font-size\"><strong>Noticias</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:uagb/post-carousel {\"btnBorderStyle\":\"none\",\"block_id\":\"c2646e9c\",\"postsToShow\":3} /-->\n\n<!-- wp:paragraph {\"fontSize\":\"large\"} -->\n<p class=\"has-large-font-size\"><strong>Contacta con nosotros</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:columns -->\n<div class=\"wp-block-columns\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:paragraph -->\n<p>Calle Periodista Alberto Machado Cayuso, 1<br>Granada, Granada</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>18014</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:paragraph -->\n<p>(+34) 123 456 789<br><a href=\"mailto:example@example.com\"><a href=\"mailto:example@example.com\">crochetandchill</a>@gmail.com</a></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:wpmapblock/wp-map-block {\"map_id\":\"wpmapblock_6fd62df9\",\"map_marker_list\":[{\"id\":0,\"lat\":37.196676623685285,\"lng\":-363.62366974353796,\"title\":\"\",\"content\":\"\",\"iconType\":\"default\",\"customIconUrl\":\"\",\"customIconWidth\":25,\"customIconHeight\":40}],\"map_zoom\":15} /-->\n\n<!-- wp:uagb/forms {\"block_id\":\"cb03a2d5\",\"submitButtonText\":\"Enviar\",\"confirmationMessage\":\"Gracias por su mensaje. Ha sido recibido.\",\"failedMessage\":\"Lo lamentamos. Hubo un error con su mensaje. Inténtelo de nuevo más tarde.\",\"afterSubmitToEmail\":\"joseruzdomínguez@hotmail.com\",\"submitborderRadius\":\"\",\"inputborderStyle\":\"\",\"inputborderWidth\":\"\",\"inputborderRadius\":\"\",\"inputborderColor\":\"\",\"labelAlignment\":\"left\",\"fieldBorderTopWidth\":1,\"fieldBorderLeftWidth\":1,\"fieldBorder