INSERT INTO `wp_snippets` (`id`, `name`, `description`, `code`, `tags`, `scope`, `condition_id`, `priority`, `active`, `modified`, `revision`, `cloud_id`) VALUES (1,'Hacer que los nombres de archivos subidos estén en minúsculas','Asegura que las subidas de imágenes y archivos tengan nombres de archivo en minúsculas.\n\nEsto es un fragmento de código de ejemplo. Siéntente libre de usarlo, editarlo o eliminarlo.','add_filter( \'sanitize_file_name\', \'mb_strtolower\' );','sample, media','global',0,10,0,'2026-04-15 20:00:34',1,NULL),
(2,'Desactivar barra de administración','Desactiva la barra de administración de WordPress para todos excepto para los administradores.\n\nEsto es un fragmento de código de ejemplo. Siéntente libre de usarlo, editarlo o eliminarlo.','add_action( \'wp\', function () {\n	if ( ! current_user_can( \'manage_options\' ) ) {\n		show_admin_bar( false );\n	}\n} );','sample, admin-bar','front-end',0,10,0,'2026-04-15 20:00:34',1,NULL),
(3,'Permitir emoticonos','Permite la conversión de emoticonos en lugares oscuros.\n\nEsto es un fragmento de código de ejemplo. Siéntente libre de usarlo, editarlo o eliminarlo.','add_filter( \'widget_text\', \'convert_smilies\' );\nadd_filter( \'the_title\', \'convert_smilies\' );\nadd_filter( \'wp_title\', \'convert_smilies\' );\nadd_filter( \'get_bloginfo\', \'convert_smilies\' );','sample','global',0,10,0,'2026-04-15 20:00:34',1,NULL),
(4,'Año actual','Shortcode para insertar el año actual en una entrada o página…\n\nEsto es un fragmento de código de ejemplo. Siéntente libre de usarlo, editarlo o eliminarlo.','<?php echo date( \'Y\' ); ?>','sample, dates','content',0,10,0,'2026-04-15 20:00:34',1,NULL),
(5,'Campos productos','','add_shortcode(\'mis_campos\', function() {\n    ob_start();\n    \n    $foto = get_field(\'foto\');\n    $tipo = get_field(\'tipo_producto\');\n    $personalizable = get_field(\'personalizable\');\n    ?>\n\n    <ul>\n        <li><strong>Precio:</strong> <?php the_field(\'precio\'); ?> €</li>\n\n        <?php if ($foto): ?>\n        <li><strong>Foto:</strong><br>\n            <img src=\"<?php echo $foto[\'url\']; ?>\" alt=\"<?php echo $foto[\'alt\']; ?>\" style=\"max-width:300px;\">\n        </li>\n        <?php endif; ?>\n\n        <li><strong>Tipo de producto:</strong> <?php the_field(\'tipo_producto\'); ?></li>\n\n        <?php if ($tipo == \'accesorio\' || $tipo == \'peluche\'): ?>\n        <li><strong>Tamaño:</strong> <?php the_field(\'tamano\'); ?></li>\n        <?php endif; ?>\n\n        <?php if ($tipo == \'ropa\'): ?>\n        <li><strong>Talla:</strong> <?php the_field(\'talla\'); ?></li>\n        <?php endif; ?>\n\n        <li><strong>Colores disponibles:</strong> <?php the_field(\'colores\'); ?></li>\n\n        <?php if ($personalizable): ?>\n        <li><strong>Opciones de personalización:</strong> <?php the_field(\'opciones_de_personalizacion\'); ?></li>\n        <?php endif; ?>\n    </ul>\n\n    <?php\n    return ob_get_clean();\n});','','global',0,10,1,'2026-04-15 20:02:11',1,NULL);
/*!40000 ALTER TABLE `wp_snippets` ENABLE KEYS */;
UNLOCK TABLES;
COMMIT;
SET AUTOCOMMIT=@OLD_AUTOCOMMIT;

